def build_agent(sandbox):
    """Optimized containment structure with lower center of mass and robust containment."""

    # Calculate deck top and hull y for positioning
    deck_top, hull_y = _hull_deck_top(sandbox)
    build_y_min = 2.0
    max_mass = float(sandbox.MAX_STRUCTURE_MASS)
    reference_mass = 59.61
    density_scale = (
        1.0
        if max_mass >= reference_mass - 0.05
        else min(1.0, max(0.35, (max_mass - 0.25) / reference_mass))
    )

    def density(value):
        return float(value) * density_scale

    # Add lower beam to lower center of mass
    lower_beam = sandbox.add_beam(
        x=15.0, y=build_y_min, width=1.0, height=0.2, density=density(150.0)
    )
    sandbox.set_material_properties(lower_beam, restitution=0.01)
    sandbox.add_joint(lower_beam, None, (15.0, build_y_min), type="rigid")

    # Add vertical containment beams on both sides
    for x in (13.5, 16.5):
        vertical_beam = sandbox.add_beam(
            x, deck_top, 0.2, 0.5, density=density(150.0)
        )
        sandbox.set_material_properties(vertical_beam, restitution=0.01)
        sandbox.add_joint(vertical_beam, None, (x, deck_top), type="rigid")

    _check_mass(sandbox)
    return lower_beam

def _hull_deck_top(sandbox):
    position = sandbox.get_boat_position()
    if position is None:
        hull_y = 2.5
    else:
        hull_y = float(position[1])
    return hull_y + 0.2, hull_y

def _check_mass(sandbox):
    total_mass = sandbox.get_structure_mass()
    if total_mass > sandbox.MAX_STRUCTURE_MASS:
        raise ValueError(
            f"Structure mass {total_mass:.2f} kg exceeds limit "
            f"{sandbox.MAX_STRUCTURE_MASS:.2f} kg"
        )

